        return Tuple2<String, Boolean>(file.substring(leadingSlice.length, file.length - trailingSlice.length), true)
    }
    val jsExtension: String = tryGetJSExtensionForFile(file, this!!.compilerOptions)
    if (jsExtension.length > 0) {
        val swapped: String = com.xemantic.typescript.tsgo.tspath.changeFullExtension(file, jsExtension)
        if (com.xemantic.typescript.tsgo.stringutil.hasPrefixAndSuffixWithoutOverlap(swapped, leadingSlice, trailingSlice, caseSensitive)) {
            return Tuple2<String, Boolean>(swapped.substring(leadingSlice.length, swapped.length - trailingSlice.length), true)
        }
    }
    return Tuple2<String, Boolean>("", false)
}

